// Signs release builds with our own keystore (credentials/keystore.properties) instead of Expo's debug key.
// android/ is generated by `expo prebuild`, so signing is configured here rather than edited by hand.
// Keep credentials/ backed up: an app can only be updated in place by a build signed with the same key.
const { withAppBuildGradle } = require("expo/config-plugins");

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let g = cfg.modResults.contents;
    if (g.includes("aanganRelease")) return cfg; // already applied

    g = g.replace(
      /^android\s*\{/m,
      `def aanganKeystoreFile = rootProject.file("../credentials/keystore.properties")
def aanganKeystore = new Properties()
if (aanganKeystoreFile.exists()) { aanganKeystore.load(new FileInputStream(aanganKeystoreFile)) }

android {
    // Windows limits paths to 260 characters and React Native's native build nests very deeply, so keep the
    // C++ scratch directory short (it resolves to <project>/c).
    externalNativeBuild { cmake { buildStagingDirectory rootProject.file("../c") } }`,
    );

    g = g.replace(
      /signingConfigs\s*\{/,
      `signingConfigs {
        aanganRelease {
            if (aanganKeystoreFile.exists()) {
                storeFile rootProject.file("../credentials/" + aanganKeystore['storeFile'])
                storePassword aanganKeystore['storePassword']
                keyAlias aanganKeystore['keyAlias']
                keyPassword aanganKeystore['keyPassword']
            }
        }`,
    );

    // The release build type signs with our key when the keystore exists, otherwise falls back to the debug key.
    g = g.replace(
      /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
      "$1signingConfig aanganKeystoreFile.exists() ? signingConfigs.aanganRelease : signingConfigs.debug",
    );

    cfg.modResults.contents = g;
    return cfg;
  });
};
